def dht(id_,name,body,spec,notes,rate,srcs,rev,colors):
    W({"id":id_,"name":name,"kind":"sensor","body":body,"colors":colors,
     "headers":[hdr(4,"VCC (leftmost, grille facing you)",note="Bare 4-pin sensor; pin 3 is NC. 3-pin PCB modules exist (pull-up fitted) and their order varies: read the silkscreen.")],
     "pins":[pin(1,"VCC","VCC",["power"],"3.3-5.5V DC"),
             pin(2,"DATA","DATA",["one-wire (Aosong single-bus, NOT Dallas 1-Wire)"],"open-drain; idles at pull-up voltage",["Needs a pull-up (Adafruit: 10k) from DATA to VCC."]),
             pin(3,"NC","NC",["nc"],"",["Not connected. Leave unwired."]),pin(4,"GND","GND",["GND"],G5)],
     "electrical":spec,
     "part":part("sensor",{"min":3.3,"max":5.5},{"level":"follows pull-up (open-drain)"},
        compat(("yes",["Power from 3V3 (pull-up to 3V3) so DATA never sees 5V."]),("yes",[])),
        {"type":"one-wire (proprietary single-bus)","sample_rate":rate},{"max":2.5,"note":"Adafruit: 2.5 mA max during conversion"},
        [{"kind":"resistor","value":"10k","between":["DATA","VCC"],"source":"Adafruit DHT guide","note":"Omit on 3-pin PCB modules that already have one."},
         {"kind":"capacitor","value":"100nF","between":["VCC","GND"],"optional":True,"source":"AM2302 sheet"}],
        "breadboard",L["dht"]),
     "provenance":prov(srcs,rev,notes)})
